import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import assert from 'node:assert/strict';
const directory = await mkdtemp(resolve('data', 'launch-check-'));
const child = spawn('npm', ['start'], {
  env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'workboard.sqlite') },
  stdio: ['ignore', 'pipe', 'inherit'],
});
try {
  const port = await new Promise((resolvePort, reject) => {
    child.once('error', reject);
    child.stdout.on('data', chunk => {
      const match = /listening on port (\d+)/.exec(String(chunk));
      if (match) resolvePort(match[1]);
    });
  });
  const response = await fetch(`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: 'ok' });
  const homepage = await fetch(`http://127.0.0.1:${port}/`);
  assert.equal(homepage.status, 200);
  assert.match(await homepage.text(), /<h1>Workboard<\/h1>/);
  console.log('npm start and health contract passed');
} finally {
  // npm forwards termination to its node server when both receive the signal.
  const children = spawn('pkill', ['-TERM', '-P', String(child.pid)]);
  await once(children, 'exit');
  const stopped = once(child, 'exit');
  child.kill('SIGTERM');
  await stopped;
  await rm(directory, { recursive: true, force: true });
}
